def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    n = int(budget / (dim * 10))
    sigma0 = 5.0
    mean = np.zeros(dim)
    cov = np.eye(dim) * 1e-4

    for _ in range(n):
        x = clip(mean + rng.normal(0, sigma0, size=dim))
        fval = func(x)

        new_x = clip(mean + rng.normal(0, sigma0, size=dim))
        fnew_val = func(new_x)

        if fnew_val < fval:
            mean = 0.5 * (mean + new_x)
            cov += 0.1 * np.outer(new_x - mean, new_x - mean)
            fval = fnew_val

    return clip(mean)

def algorithm(func, dim, lb, ub, budget, rng):
    def evaluate(x):
        return func(x) + 10*dim

    def clip(x):
        return np.clip(x, lb, ub)

    pop_size = int(np.sqrt(budget))
    mu = np.random.uniform(lb, ub, (pop_size, dim))

    for i in range(budget - pop_size):
        sigma = 0.5
        for _ in range(100):
            x_new = clip(mu + rng.normal(size=(mu.shape[0], dim))*sigma)
            f_new = evaluate(x_new)
            mu = np.where(f_new < func(mu), x_new, mu)

    return np.argmin(func(mu))
